1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"os"
7		"reflect"
8		"testing"
9	)
10	
11	// 本文件为 Query 查询结果与真实账本之间的独立性提供回归保障：
12	//
13	//  1. 时效独立：先前取得的快照是“当时的账单”，后续付款/退款改变账本后，
14	//     旧快照的余额、记录数量与记录内容一律保持原样；新记录只出现在新查询中。
15	//  2. 空间独立：调用者可以任意调整返回的余额、结算记录、退款记录供自己展示，
16	//     篡改只影响自己那份；另一份独立取得的结果与再次查询的真实数据都不受影响。
17	//  3. 判定独立：对返回数据的任何改动都不能影响后续付款按真实余额结算，
18	//     也不能改变原付款是否已结算/已退款的判断。
19	//  4. 只读：仅查询或修改返回数据时，账本文件字节与成功记录数量保持不变。
20	//
21	// 查询入口与 Snapshot 中余额、结算、退款三个列表的公开 JSON 格式同样锁定。
22	
23	func mustQuery(t *testing.T, l *Ledger) *Snapshot {
24		t.Helper()
25		snap, err := l.Query()
26		if err != nil {
27			t.Fatalf("Query: %v", err)
28		}
29		return snap
30	}
31	
32	func mustSettle(t *testing.T, l *Ledger, bps int, it PaymentIntent) ItemResult {
33		t.Helper()
34		res, err := l.Submit(FeeBatch{FeeBps: bps, Intents: []PaymentIntent{it}})
35		if err != nil {
36			t.Fatalf("submit %q: %v", it.ID, err)
37		}
38		return res.Results[0]
39	}
40	
41	func mustRefundOne(t *testing.T, l *Ledger, id, sid, reason string) RefundResult {
42		t.Helper()
43		res, err := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq(id, sid, reason)}})
44		if err != nil {
45			t.Fatalf("refund %q: %v", id, err)
46		}
47		return res.Results[0]
48	}
49	
50	func assertSnap(t *testing.T, got, want *Snapshot, label string) {
51		t.Helper()
52		if !reflect.DeepEqual(got.Balances, want.Balances) {
53			t.Fatalf("%s balances:\n got %#v\nwant %#v", label, got.Balances, want.Balances)
54		}
55		if !reflect.DeepEqual(got.Settlements, want.Settlements) {
56			t.Fatalf("%s settlements:\n got %#v\nwant %#v", label, got.Settlements, want.Settlements)
57		}
58		if !reflect.DeepEqual(got.Refunds, want.Refunds) {
59			t.Fatalf("%s refunds:\n got %#v\nwant %#v", label, got.Refunds, want.Refunds)
60		}
61	}
62	
63	// TestQuerySnapshotFreezesAcrossPaymentAndRefund 覆盖带手续费付款与全额退款
64	// 发生前后的查询结果：旧快照冻结在取得时刻，新查询反映最新真实账本。
65	func TestQuerySnapshotFreezesAcrossPaymentAndRefund(t *testing.T) {
66		path := newTestLedger(t, []BalanceInit{
67			{Account: "aa", Asset: "eth", Balance: 3},
68			{Account: "aa", Asset: "usdc", Balance: 2000},
69			{Account: "bb", Asset: "usdc", Balance: 500},
70		})
71		l := openOrFail(t, path)
72	
73		p1 := intent("p1", "aa", "usdc", 1000) // 100bps：fee=10, charged=1010
74		p2 := intent("p2", "bb", "usdc", 200)  // 0bps：charged=200
75	
76		// 1. 尚无付款或退款时取得空历史。
77		snap0 := mustQuery(t, l)
78		want0 := &Snapshot{
79			Balances: []BalanceView{
80				{Account: "aa", Asset: "eth", Balance: 3},
81				{Account: "aa", Asset: "usdc", Balance: 2000},
82				{Account: "bb", Asset: "usdc", Balance: 500},
83			},
84			Settlements: []Record{},
85			Refunds:     []RefundRecord{},
86		}
87		assertSnap(t, snap0, want0, "snap0 empty history")
88	
89		// 公开格式回归：三个列表键名固定，空列表序列化为 [] 而不是 null。
90		raw0, err := json.Marshal(snap0)
91		if err != nil {
92			t.Fatal(err)
93		}
94		for _, frag := range []string{`"balances":[`, `"settlements":[]`, `"refunds":[]`} {
95			if !bytes.Contains(raw0, []byte(frag)) {
96				t.Fatalf("snapshot JSON missing %s:\n%s", frag, raw0)
97			}
98		}
99	
100		// 2. 带手续费付款成功：新查询显示金额与手续费一并扣除后的余额与结算记录。
101		if r := mustSettle(t, l, 100, p1); r.Status != StatusSettled {
102			t.Fatalf("p1: %+v", r)
103		}
104		want1 := &Snapshot{
105			Balances: []BalanceView{
106				{Account: "aa", Asset: "eth", Balance: 3},
107				{Account: "aa", Asset: "usdc", Balance: 990}, // 2000-1010
108				{Account: "bb", Asset: "usdc", Balance: 500},
109			},
110			Settlements: []Record{{
111				ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc",
112				Amount: 1000, Nonce: 1, FeeBps: 100, Fee: 10, Charged: 1010, Seq: 1,
113			}},
114			Refunds: []RefundRecord{},
115		}
116		snap1 := mustQuery(t, l)
117		assertSnap(t, snap1, want1, "snap1 after p1")
118	
119		// 先前的空历史不跟随付款变化：余额、记录数量仍保持原样。
120		assertSnap(t, snap0, want0, "snap0 frozen after p1")
121	
122		// 3. 第二笔付款落在另一账户/资产；随后全额退回 p1（含手续费）。
123		if r := mustSettle(t, l, 0, p2); r.Status != StatusSettled {
124			t.Fatalf("p2: %+v", r)
125		}
126		if r := mustRefundOne(t, l, "r1", "p1", "cancel order"); r.Status != StatusRefundSuccess {
127			t.Fatalf("r1: %+v", r)
128		}
129		want2 := &Snapshot{
130			Balances: []BalanceView{
131				{Account: "aa", Asset: "eth", Balance: 3}, // 未发生收支的组合保持原余额
132				{Account: "aa", Asset: "usdc", Balance: 2000}, // 990+1010 回到原扣款总额
133				{Account: "bb", Asset: "usdc", Balance: 300},  // 500-200
134			},
135			Settlements: []Record{
136				{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc",
137					Amount: 1000, Nonce: 1, FeeBps: 100, Fee: 10, Charged: 1010, Seq: 1},
138				{ID: "p2", Account: "bb", Paymaster: "pm", Asset: "usdc",
139					Amount: 200, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 200, Seq: 2},
140			},
141			Refunds: []RefundRecord{{
142				ID: "r1", SettlementID: "p1", Reason: "cancel order",
143				Account: "aa", Asset: "usdc", Amount: 1000, Fee: 10, Charged: 1010,
144				AfterSeq: 2, Seq: 1,
145			}},
146		}
147		snap2 := mustQuery(t, l)
148		assertSnap(t, snap2, want2, "snap2 after r1")
149		// 原结算仍然保留、内容未被退款改写（want2 中 p1 的 charged 仍为 1010）。
150	
151		// 4. 第二笔退款：退款记录按成功先后排列；无关组合 eth 不动。
152		if r := mustRefundOne(t, l, "r2", "p2", "user asked"); r.Status != StatusRefundSuccess {
153			t.Fatalf("r2: %+v", r)
154		}
155		want3 := &Snapshot{
156			Balances: []BalanceView{
157				{Account: "aa", Asset: "eth", Balance: 3},
158				{Account: "aa", Asset: "usdc", Balance: 2000},
159				{Account: "bb", Asset: "usdc", Balance: 500}, // 300+200
160			},
161			Settlements: want2.Settlements, // 结算列表内容与顺序不再变化
162			Refunds: []RefundRecord{
163				{ID: "r1", SettlementID: "p1", Reason: "cancel order",
164					Account: "aa", Asset: "usdc", Amount: 1000, Fee: 10, Charged: 1010,
165					AfterSeq: 2, Seq: 1},
166				{ID: "r2", SettlementID: "p2", Reason: "user asked",
167					Account: "bb", Asset: "usdc", Amount: 200, Fee: 0, Charged: 200,
168					AfterSeq: 2, Seq: 2},
169			},
170		}
171		snap3 := mustQuery(t, l)
172		assertSnap(t, snap3, want3, "snap3 after r2")
173	
174		// 5. 所有先前快照继续冻结在各自的取得时刻：余额、记录数量、记录内容均不变。
175		assertSnap(t, snap0, want0, "snap0 frozen at end")
176		assertSnap(t, snap1, want1, "snap1 frozen after refund")
177		assertSnap(t, snap2, want2, "snap2 frozen after r2")
178	
179		// 公开 JSON 格式可往返，三个列表与字段名保持兼容。
180		raw3, err := json.Marshal(snap3)
181		if err != nil {
182			t.Fatal(err)
183		}
184		var roundTrip Snapshot
185		if err := json.Unmarshal(raw3, &roundTrip); err != nil {
186			t.Fatal(err)
187		}
188		assertSnap(t, &roundTrip, want3, "json round trip")
189	}
190	
191	// TestQueryEmptyHistoryStaysEmpty 专门锁定：尚无任何记录时取得的空历史，
192	// 在后续付款、退款发生后仍必须为空；新记录只能出现在新查询里。
193	func TestQueryEmptyHistoryStaysEmpty(t *testing.T) {
194		path := newTestLedger(t, []BalanceInit{
195			{Account: "aa", Asset: "usdc", Balance: 100},
196			{Account: "bb", Asset: "usdc", Balance: 100},
197		})
198		l := openOrFail(t, path)
199	
200		empty := mustQuery(t, l)
201		if len(empty.Settlements) != 0 || len(empty.Refunds) != 0 {
202			t.Fatalf("initial history must be empty: %+v", empty)
203		}
204		emptyBal := append([]BalanceView(nil), empty.Balances...)
205	
206		// 账本在另一个账户上发生完整的付款 → 退款。
207		if r := mustSettle(t, l, 100, intent("p1", "bb", "usdc", 50)); r.Status != StatusSettled {
208			t.Fatalf("p1: %+v", r) // charged 51（50+1），bb 余 49
209		}
210		if r := mustRefundOne(t, l, "r1", "p1", "oops"); r.Status != StatusRefundSuccess {
211			t.Fatalf("r1: %+v", r) // bb 回到 100
212		}
213	
214		// 旧空快照仍为空，且余额仍是当时内容（aa 100、bb 100）。
215		if len(empty.Settlements) != 0 || len(empty.Refunds) != 0 {
216			t.Fatalf("old snapshot history must stay empty: settlements=%d refunds=%d",
217				len(empty.Settlements), len(empty.Refunds))
218		}
219		if !reflect.DeepEqual(empty.Balances, emptyBal) {
220			t.Fatalf("old snapshot balances changed: %#v", empty.Balances)
221		}
222	
223		// 新查询包含新记录，且不影响旧快照的空列表。
224		fresh := mustQuery(t, l)
225		if len(fresh.Settlements) != 1 || fresh.Settlements[0].ID != "p1" {
226			t.Fatalf("new query must carry the payment: %+v", fresh.Settlements)
227		}
228		if len(fresh.Refunds) != 1 || fresh.Refunds[0].SettlementID != "p1" {
229			t.Fatalf("new query must carry the refund: %+v", fresh.Refunds)
230		}
231		if len(empty.Settlements) != 0 || len(empty.Refunds) != 0 {
232			t.Fatalf("taking a new query must not populate the old snapshot")
233		}
234	}
235	
236	// TestQueryCallerEditsStayPrivate 验证调用者对返回结果的改写只能影响自己那份：
237	// 余额与三类列表的元素、追加、重排都不能污染真实账本或另一份独立结果；
238	// 余额和历史必须一起受到保护，再次查询仍得到真实业务数据。
239	func TestQueryCallerEditsStayPrivate(t *testing.T) {
240		path := newTestLedger(t, []BalanceInit{
241			{Account: "aa", Asset: "usdc", Balance: 5000},
242			{Account: "bb", Asset: "usdc", Balance: 1000},
243		})
244		l := openOrFail(t, path)
245	
246		// 真实业务：p1 带手续费成功后被 r1 全额退款；之后 p2、p3 分别在两个账户成功。
247		if r := mustSettle(t, l, 100, intent("p1", "aa", "usdc", 1000)); r.Status != StatusSettled {
248			t.Fatalf("p1: %+v", r) // charged 1010
249		}
250		if r := mustRefundOne(t, l, "r1", "p1", "bad charge"); r.Status != StatusRefundSuccess {
251			t.Fatalf("r1: %+v", r) // 退回 1010，r1 落账时只有 1 笔结算（after_seq=1）
252		}
253		if r := mustSettle(t, l, 0, intent("p2", "aa", "usdc", 2000)); r.Status != StatusSettled {
254			t.Fatalf("p2: %+v", r) // aa 余 3000
255		}
256		if r := mustSettle(t, l, 50, intent("p3", "bb", "usdc", 400)); r.Status != StatusSettled {
257			t.Fatalf("p3: %+v", r) // fee=2, charged 402，bb 余 598
258		}
259	
260		wantFrozen := &Snapshot{
261			Balances: []BalanceView{
262				{Account: "aa", Asset: "usdc", Balance: 3000},
263				{Account: "bb", Asset: "usdc", Balance: 598},
264			},
265			Settlements: []Record{
266				{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc",
267					Amount: 1000, Nonce: 1, FeeBps: 100, Fee: 10, Charged: 1010, Seq: 1},
268				{ID: "p2", Account: "aa", Paymaster: "pm", Asset: "usdc",
269					Amount: 2000, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 2000, Seq: 2},
270				{ID: "p3", Account: "bb", Paymaster: "pm", Asset: "usdc",
271					Amount: 400, Nonce: 1, FeeBps: 50, Fee: 2, Charged: 402, Seq: 3},
272			},
273			Refunds: []RefundRecord{{
274				ID: "r1", SettlementID: "p1", Reason: "bad charge",
275				Account: "aa", Asset: "usdc", Amount: 1000, Fee: 10, Charged: 1010,
276				AfterSeq: 1, Seq: 1,
277			}},
278		}
279	
280		// 两份独立取得的结果初始一致。
281		snapA := mustQuery(t, l)
282		snapB := mustQuery(t, l)
283		assertSnap(t, snapA, wantFrozen, "snapA before edits")
284		assertSnap(t, snapB, wantFrozen, "snapB before edits")
285	
286		// 像调用者为自己展示所做的那样，任意改写 snapA：余额、结算、退款、追加与重排。
287		snapA.Balances[0].Account = "zz"
288		snapA.Balances[0].Asset = "btc"
289		snapA.Balances[0].Balance = 999_999
290		snapA.Balances = append(snapA.Balances, BalanceView{Account: "fake", Asset: "fake", Balance: 1})
291		snapA.Settlements[0].ID = "HACK"
292		snapA.Settlements[0].Account = "zz"
293		snapA.Settlements[0].Paymaster = "fake-pm"
294		snapA.Settlements[0].Asset = "btc"
295		snapA.Settlements[0].Amount = 1
296		snapA.Settlements[0].Nonce = 4242
297		snapA.Settlements[0].FeeBps = 9999
298		snapA.Settlements[0].Fee = 9
299		snapA.Settlements[0].Charged = 99
300		snapA.Settlements[0].Seq = 77
301		snapA.Settlements[1], snapA.Settlements[2] = snapA.Settlements[2], snapA.Settlements[1]
302		snapA.Settlements = append(snapA.Settlements, Record{ID: "fake-pay"})
303		snapA.Refunds[0].ID = "HACK-REF"
304		snapA.Refunds[0].SettlementID = "p2"
305		snapA.Refunds[0].Reason = "forged"
306		snapA.Refunds[0].Account = "zz"
307		snapA.Refunds[0].Asset = "btc"
308		snapA.Refunds[0].Amount = 1
309		snapA.Refunds[0].Fee = 1
310		snapA.Refunds[0].Charged = 2
311		snapA.Refunds[0].AfterSeq = 99
312		snapA.Refunds[0].Seq = 99
313		snapA.Refunds = append(snapA.Refunds, RefundRecord{ID: "fake-ref"})
314	
315		// 此前独立取得的另一份结果不能被改写波及（余额与历史一起受保护）。
316		assertSnap(t, snapB, wantFrozen, "snapB after editing snapA")
317	
318		// 再次查询仍得到真实业务产生的数据：原编号、账户、资产、金额、手续费、
319		// 成功序号，以及退款原因和关联原付款全部完整。
320		snapC := mustQuery(t, l)
321		assertSnap(t, snapC, wantFrozen, "ledger after editing snapA")
322		rp1 := snapC.Settlements[0]
323		if rp1.ID != "p1" || rp1.Account != "aa" || rp1.Asset != "usdc" ||
324			rp1.Amount != 1000 || rp1.Fee != 10 || rp1.FeeBps != 100 || rp1.Seq != 1 {
325			t.Fatalf("real p1 record lost after caller edit: %+v", rp1)
326		}
327		rr1 := snapC.Refunds[0]
328		if rr1.ID != "r1" || rr1.Reason != "bad charge" || rr1.SettlementID != "p1" ||
329			rr1.Account != "aa" || rr1.Asset != "usdc" || rr1.Amount != 1000 ||
330			rr1.Fee != 10 || rr1.Charged != 1010 || rr1.Seq != 1 {
331			t.Fatalf("real r1 record lost after caller edit: %+v", rr1)
332		}
333	
334		// 对返回数据的改动不能改变业务判定：
335		// 已退款的原付款按原请求再提交，仍返回 duplicate 和原结算记录，不再次扣款。
336		dup := mustSettle(t, l, 100, intent("p1", "aa", "usdc", 1000))
337		if dup.Status != StatusDuplicate || dup.Record == nil ||
338			dup.Record.Seq != 1 || dup.Record.Charged != 1010 {
339			t.Fatalf("refunded payment retry want duplicate with original record: %+v", dup)
340		}
341		if bal, _ := l.Balance("aa", "usdc"); bal != 3000 {
342			t.Fatalf("duplicate after snapshot edit charged again: bal=%d", bal)
343		}
344	
345		// 用新的退款编号申请退回同一付款：仍为 already_refunded，不增加余额。
346		rx := mustRefundOne(t, l, "rx", "p1", "trying again")
347		if rx.Status != StatusAlreadyRefunded {
348			t.Fatalf("want already_refunded, got %+v", rx)
349		}
350		if bal, _ := l.Balance("aa", "usdc"); bal != 3000 {
351			t.Fatalf("already_refunded after snapshot edit changed balance: %d", bal)
352		}
353	
354		// 后续付款仍按真实余额结算（篡改既没有抬高也没有压低可用余额）。
355		p4 := mustSettle(t, l, 0, intent("p4", "aa", "usdc", 3000))
356		if p4.Status != StatusSettled || p4.Record.Seq != 4 {
357			t.Fatalf("payment must settle against the real balance: %+v", p4)
358		}
359		final := mustQuery(t, l)
360		if final.Balances[0].Balance != 0 || final.Balances[1].Balance != 598 {
361			t.Fatalf("final balances: %+v", final.Balances)
362		}
363		if len(final.Settlements) != 4 || len(final.Refunds) != 1 {
364			t.Fatalf("final history counts: settlements=%d refunds=%d",
365				len(final.Settlements), len(final.Refunds))
366		}
367	}
368	
369	// TestQueryEditCannotRaiseSpendingLimit 验证篡改返回数据（改大余额、伪造记录）
370	// 不能提升调用者的购买力，也不能让伪造编号在真实账本中被当成已结算。
371	func TestQueryEditCannotRaiseSpendingLimit(t *testing.T) {
372		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
373		l := openOrFail(t, path)
374	
375		if r := mustSettle(t, l, 0, intent("p1", "aa", "usdc", 30)); r.Status != StatusSettled {
376			t.Fatalf("p1: %+v", r) // 真实余额 70
377		}
378	
379		snap := mustQuery(t, l)
380		for i := range snap.Balances {
381			if snap.Balances[i].Account == "aa" && snap.Balances[i].Asset == "usdc" {
382				snap.Balances[i].Balance = 1_000_000
383			}
384		}
385		snap.Balances = append(snap.Balances, BalanceView{Account: "ghost", Asset: "gold", Balance: 7})
386		snap.Settlements[0].Charged = 0
387		snap.Settlements[0].Amount = 0
388		// 追加一条伪造成功记录：若查询与账本共享底层数组，这会直接污染真实历史。
389		snap.Settlements = append(snap.Settlements, Record{
390			ID: "fake", Account: "aa", Paymaster: "pm", Asset: "usdc",
391			Amount: 10, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 10, Seq: 99,
392		})
393	
394		// 真实余额未被抬高：超出 70 的付款仍失败。
395		if r := mustSettle(t, l, 0, intent("p2", "aa", "usdc", 71)); r.Status != StatusFunds {
396			t.Fatalf("inflated snapshot balance must not enable overspend: %+v", r)
397		}
398	
399		// 伪造编号没有进入真实历史：同编号同字段的请求按首次付款处理并成功，
400		// 而不是 duplicate；扣款依据真实余额 70。
401		fake := mustSettle(t, l, 0, intent("fake", "aa", "usdc", 10))
402		if fake.Status != StatusSettled || fake.Record.Seq != 2 {
403			t.Fatalf("forged record must not exist in the real ledger: %+v", fake)
404		}
405		if bal, _ := l.Balance("aa", "usdc"); bal != 60 {
406			t.Fatalf("real balance=%d want 60", bal)
407		}
408		again := mustQuery(t, l)
409		if len(again.Settlements) != 2 || again.Settlements[0].Amount != 30 || again.Settlements[0].Charged != 30 {
410			t.Fatalf("real p1 record must stay intact: %+v", again.Settlements)
411		}
412		if len(again.Balances) != 1 {
413			t.Fatalf("forged balance entry leaked into the ledger: %+v", again.Balances)
414		}
415	}
416	
417	// TestQueryAndCallerEditsDoNotRewriteLedgerFile 验证仅查询或修改返回数据时，
418	// 账本文件字节内容与成功记录数量都保持不变。
419	func TestQueryAndCallerEditsDoNotRewriteLedgerFile(t *testing.T) {
420		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
421		l := openOrFail(t, path)
422	
423		// 先产生一笔付款与一笔退款，使余额、结算、退款三类数据都存在。
424		if r := mustSettle(t, l, 100, intent("p1", "aa", "usdc", 300)); r.Status != StatusSettled {
425			t.Fatalf("p1: %+v", r) // charged 303
426		}
427		if r := mustRefundOne(t, l, "r1", "p1", "review"); r.Status != StatusRefundSuccess {
428			t.Fatalf("r1: %+v", r)
429		}
430	
431		before, err := os.ReadFile(path)
432		if err != nil {
433			t.Fatal(err)
434		}
435	
436		// 反复查询，每次都对自己的返回结果做破坏性改写；查询不得触发任何写盘。
437		for i := 0; i < 3; i++ {
438			snap := mustQuery(t, l)
439			for j := range snap.Balances {
440				snap.Balances[j].Balance = int64(-(i + 1))
441				snap.Balances[j].Account = "mutated"
442			}
443			snap.Balances = append(snap.Balances, BalanceView{Account: "x", Asset: "y", Balance: 9})
444			for j := range snap.Settlements {
445				snap.Settlements[j].ID = "MUTATED"
446				snap.Settlements[j].Charged = -1
447				snap.Settlements[j].Seq = int64(100 + i)
448			}
449			snap.Settlements = append(snap.Settlements, Record{ID: "mutated-pay"})
450			for j := range snap.Refunds {
451				snap.Refunds[j].ID = "MUTATED-REF"
452				snap.Refunds[j].Reason = ""
453				snap.Refunds[j].SettlementID = "ghost"
454			}
455			snap.Refunds = append(snap.Refunds, RefundRecord{ID: "mutated-ref"})
456			if _, err := json.Marshal(snap); err != nil {
457				t.Fatal(err)
458			}
459		}
460	
461		after, err := os.ReadFile(path)
462		if err != nil {
463			t.Fatal(err)
464		}
465		if !bytes.Equal(before, after) {
466			t.Fatalf("ledger file changed after queries and caller edits:\nbefore=%s\nafter =%s", before, after)
467		}
468	
469		// 成功记录数量与内容保持不变。
470		snap := mustQuery(t, l)
471		if len(snap.Settlements) != 1 || snap.Settlements[0].ID != "p1" || snap.Settlements[0].Charged != 303 {
472			t.Fatalf("settlement record changed: %+v", snap.Settlements)
473		}
474		if len(snap.Refunds) != 1 || snap.Refunds[0].ID != "r1" || snap.Refunds[0].SettlementID != "p1" {
475			t.Fatalf("refund record changed: %+v", snap.Refunds)
476		}
477		if bal, _ := l.Balance("aa", "usdc"); bal != 1000 {
478			t.Fatalf("balance changed: %d", bal)
479		}
480	}
