93			refundReq("rb", "p2", reasonTwoFail),  // 2) 保存失败一次
94			refundReq("rb", "p3", reasonThree),    // 3) 复用失败编号：换另一笔付款、换原因
95			refundReq("rb", "p3", reasonThree),    // 4) 原样重复 3)
96			refundReq("rc", "p2", reasonTwoRetry), // 5) 新编号退回第二笔付款
97		}})
98		if err != nil {
99			t.Fatalf("refund batch must not fail as a whole: %v", err)
100		}
101		if len(rr.Results) != 5 {
102			t.Fatalf("results len=%d want 5 (逐项对应输入)", len(rr.Results))
103		}
104	
105		// 状态序列严格按输入顺序对应：成功 / 存储失败 / 成功 / 重复 / 成功。
106		wantStatus := []string{
107			StatusRefundSuccess, StatusStorage, StatusRefundSuccess, StatusDuplicate, StatusRefundSuccess,
108		}
109		if got := refundStatuses(rr); !reflect.DeepEqual(got, wantStatus) {
110			t.Fatalf("statuses=%v want %v", got, wantStatus)
111		}
112	
113		// 留存失败项结果：同编号申请随后成功后，它仍必须保持失败，不被成功详情覆盖。
114		failed := rr.Results[1]
115		if failed.Status != StatusStorage {
116			t.Fatalf("item 2 status=%s want storage_error", failed.Status)
117		}
118		if failed.Reason == "" || !strings.Contains(failed.Reason, "injected write failure") {
119			t.Fatalf("item 2 must carry the failure explanation, got %q", failed.Reason)
120		}
121	
122		// 三笔成功退款的预期记录：全部 after_seq=3（三笔付款早已存在），成功序号
123		// 连续为 1/2/3——失败项与重复项都不占序号；复用编号 rb 只对应后来成功的
124		// 目标 p3 与原因三。
125		wantRA := RefundRecord{
126			ID: "ra", SettlementID: "p1", Reason: reasonOne,
127			Account: "aa", Asset: "usdc", Amount: 1000, Fee: 10, Charged: 1010,
128			AfterSeq: 3, Seq: 1,
129		}
130		wantRB := RefundRecord{
131			ID: "rb", SettlementID: "p3", Reason: reasonThree,
132			Account: "aa", Asset: "usdc", Amount: 2000, Fee: 10, Charged: 2010,
133			AfterSeq: 3, Seq: 2,
134		}
135		wantRC := RefundRecord{
136			ID: "rc", SettlementID: "p2", Reason: reasonTwoRetry,
137			Account: "aa", Asset: "usdc", Amount: 1500, Fee: 4, Charged: 1504,
138			AfterSeq: 3, Seq: 3,
139		}
140		// 成功项与紧随的重复项指向第三笔付款、记录修改后的原因、按原付款 charged
141		// 全额（含当时手续费）退回原账户与原资产；两者逐字段一致。
142		assertRefundResultRecord(t, rr.Results[0], StatusRefundSuccess, wantRA)
143		assertRefundResultRecord(t, rr.Results[2], StatusRefundSuccess, wantRB)
144		assertRefundResultRecord(t, rr.Results[3], StatusDuplicate, wantRB)
145		assertRefundResultRecord(t, rr.Results[4], StatusRefundSuccess, wantRC)
146		// 重复项必须携带刚刚成功的退款记录，且与成功项持有各自独立的副本。
147		if rr.Results[2].Record == nil || rr.Results[3].Record == nil {
148			t.Fatalf("success/duplicate must both carry records: %+v", rr.Results)
149		}
150		if rr.Results[2].Record == rr.Results[3].Record {
151			t.Fatal("success and duplicate results share one *RefundRecord allocation")
152		}
153		if rr.Results[3].SettlementID != "p3" || rr.Results[3].Account != "aa" ||
154			rr.Results[3].Asset != "usdc" || rr.Results[3].Reason != reasonThree ||
155			rr.Results[3].Charged != 2010 {
156			t.Fatalf("duplicate must point at p3 with the reused reason: %+v", rr.Results[3])
157		}
158	
159		// 失败项在同编号申请成功后仍保持失败：只有状态与说明，不携带成功退款记录，
160		// 也不带任何去向详情。
161		if failed.ID != "rb" || failed.Status != StatusStorage {
162			t.Fatalf("failed result overwritten by later success: %+v", failed)
163		}
164		if failed.Record != nil {
165			t.Fatalf("storage_error must not carry a refund record: %+v", failed.Record)
166		}
167		if failed.SettlementID != "" || failed.Account != "" || failed.Asset != "" || failed.Charged != 0 {
168			t.Fatalf("storage_error must not carry success detail: %+v", failed)
169		}
170		if !strings.Contains(failed.Reason, "injected write failure") {
171			t.Fatalf("failed result lost its explanation: %q", failed.Reason)
172		}
173	
174		// 余额只增加三笔实际成功退款的总额（1010+2010+1504=4524），重复申请不入账，
175		// 保存失败项不加余额：余额恰好回到初始值。
176		if bal, _ := l.Balance("aa", "usdc"); bal != initial {
177			t.Fatalf("balance after batch=%d want %d (three successful refunds only)", bal, initial)
178		}
179	
180		// 查询到的退款历史只保留成功记录，按成功先后排列、序号连续；复用编号 rb
181		// 只对应 p3 与原因三，找不到任何 rb -> p2 的痕迹。
182		wantRefunds := []RefundRecord{wantRA, wantRB, wantRC}
183		snap := mustQuery(t, l)
184		if !reflect.DeepEqual(snap.Refunds, wantRefunds) {
185			t.Fatalf("refund history:\n got %+v\nwant %+v", snap.Refunds, wantRefunds)
186		}
187		// 三笔原付款的编号、金额、手续费、序号与成功顺序保持原样。
188		if !reflect.DeepEqual(snap.Settlements, wantSettlements) {
189			t.Fatalf("settlements altered:\n got %+v\nwant %+v", snap.Settlements, wantSettlements)
190		}
191		if len(snap.Balances) != 1 || snap.Balances[0] != (BalanceView{Account: "aa", Asset: "usdc", Balance: initial}) {
192			t.Fatalf("balance view: %+v", snap.Balances)
193		}
194	
195		// 磁盘字节层面同样不留失败申请的痕迹：失败原因不落盘，三个成功原因都在。
196		raw, err := os.ReadFile(path)
197		if err != nil {
198			t.Fatal(err)
199		}
200		if strings.Contains(string(raw), reasonTwoFail) {
201			t.Fatalf("failed refund request persisted to ledger file:\n%s", raw)
202		}
203		for _, frag := range []string{
204			`"id":"ra"`, `"settlement_id":"p1"`, `"reason":"` + reasonOne + `"`,
205			`"id":"rb"`, `"settlement_id":"p3"`, `"reason":"` + reasonThree + `"`, `"seq":2`,
206			`"id":"rc"`, `"settlement_id":"p2"`, `"reason":"` + reasonTwoRetry + `"`, `"seq":3`,
207		} {
208			if !strings.Contains(string(raw), frag) {
209				t.Fatalf("ledger file missing %s:\n%s", frag, raw)
210			}
211		}
212	
213		// 关闭重开（新进程语义）：实际保存的账本与此前查询结果完全一致。
214		if err := l.Close(); err != nil {
215			t.Fatal(err)
216		}
217		l2 := openOrFail(t, path)
218		snap2 := mustQuery(t, l2)
219		if !reflect.DeepEqual(snap2.Refunds, wantRefunds) {
220			t.Fatalf("refunds after reopen:\n got %+v\nwant %+v", snap2.Refunds, wantRefunds)
221		}
222		if !reflect.DeepEqual(snap2.Settlements, wantSettlements) {
223			t.Fatalf("settlements after reopen:\n got %+v\nwant %+v", snap2.Settlements, wantSettlements)
224		}
225		if bal, _ := l2.Balance("aa", "usdc"); bal != initial {
226			t.Fatalf("balance after reopen=%d want %d", bal, initial)
227		}
228	
229		// 重开后的后续判定沿用既有规则，且均不再入账：
230		// 原样重复成功申请仍 duplicate 并携带同一条成功记录（rb 只指向 p3）；
231		// 再换新编号退 p2 得到 already_refunded——它恰好是被 rc 退回的，
232		// 先前那次保存失败没有占用它的退款资格，但成功的 rc 已经占用。
233		dup := mustRefundOne(t, l2, "rb", "p3", reasonThree)
234		assertRefundResultRecord(t, dup, StatusDuplicate, wantRB)
235		againP2 := mustRefundOne(t, l2, "rd", "p2", "yet another id")
236		if againP2.Status != StatusAlreadyRefunded {
237			t.Fatalf("p2 must be refunded exactly once (by rc): %+v", againP2)
238		}
239		if againP2.Record != nil {
240			t.Fatalf("already_refunded must not carry a record: %+v", againP2.Record)
241		}
242		dupRA := mustRefundOne(t, l2, "ra", "p1", reasonOne)
243		assertRefundResultRecord(t, dupRA, StatusDuplicate, wantRA)
244		if bal, _ := l2.Balance("aa", "usdc"); bal != initial {
245			t.Fatalf("follow-up duplicates/already_refunded changed balance: %d want %d", bal, initial)
246		}
247		if got := mustQuery(t, l2).Refunds; !reflect.DeepEqual(got, wantRefunds) {
248			t.Fatalf("refund history changed after follow-ups:\n got %+v\nwant %+v", got, wantRefunds)
249		}
250	}
